{"results": [{"id": "hp_doc_e9eb6b52572522b3eb4889cde127ede98f5879c7cf74b90df6559c92df08b46f", "title": "Kevin Cheng", "text": "Kevin Cheng Ka-wing (born 15 August 1969) is a Hong Kong American actor and singer who is currently under the management of the Hong Kong television network TVB. Cheng rose to fame in late 2004 after playing his first lead role in the TVB drama \"Hard Fate\".", "score": 43.7005}, {"id": "hp_doc_af94b663376439b221a06cb12438f1ba923f8c70968a0a5a62533e88937aefd4", "title": "Hard Fate", "text": "Hard Fate (Traditional Chinese - 翡翠戀曲) is a 30-episode series which aired on TVB in 2004. It stars Flora Chan 陳慧珊, Damian Lau 劉松仁, Kevin Cheng 鄭嘉穎 and Niki Chow 周麗淇.", "score": 43.397}, {"id": "hp_doc_b200c4141ba03708f3b661f040771f40c4fe2b3568d36c338da1d0b03f334009", "title": "Placebo Cure", "text": "Placebo Cure is a Hong Kong modern serial drama produced by TVB and starring Sunny Chan, Joyce Tang and Kevin Cheng. The drama was filmed from November 2003 to early 2004 and was first released overseas in May 2005. It was then aired in Hong Kong on Super Sun's TVB Drama channel from 30 May to 24 June 2005. It was then aired on TVB Jade from 19 October to 16 November 2006.", "score": 22.4054}], "remaining_searches": 2}
